    /**
     * Método encargado de mostrar las opciones durante el turno del jugador en
     * la batalla.
     *
     * @param personaje Personaje del jugador al cual le corresponden las
     * características.
     */
    public static void verOpcionesBatalla(Personaje personaje) {
        System.out.println("..............................................................................................................................................................................................");
        System.out.println(". TURNO DE: " + personaje.getNombre() + "         .                                                                                                                                                               .");
        System.out.println(". ORO: " + personaje.getOro() + "                   .                                                                                                                                                               .");
        System.out.println(". VIDA: " + personaje.getHp() + "/" + personaje.getHpMaximo() + "              .    ┌-------------------------------┐   ┌----------------------------------┐   ┌----------------------------------┐   ┌-----------------------------------┐    .");
        System.out.println(". MANA: " + personaje.getMp() + "/" + personaje.getMpMaximo() + "                .    ¦            ATACAR             ¦   ¦               CURAR              ¦   ¦            USAR ITEM             ¦   ¦            TENGO MIEDO            ¦    .");
        System.out.println(". NIVEL: " + personaje.getNivel() + "                   .    ¦             [1]               ¦   ¦                [2]               ¦   ¦               [3]                ¦   ¦                 [4]               ¦    .");
        System.out.println(". EXPERIENCIA: " + personaje.getExperiencia() + "           .    └-------------------------------┘   └----------------------------------┘   └----------------------------------┘   └-----------------------------------┘    .");
        System.out.println("..............................                                                                                                                                                               .");
        System.out.println(".   Seleccione una opción    .                                                                                                                                                               .");
        System.out.println("..............................................................................................................................................................................................");
    }

